def subtract(a, b):
    def clean(intervals):
        return [iv for iv in intervals if iv[0] < iv[1]]

    a = clean(a)
    b = clean(b)

    if not a:
        return []

    points = set()
    for s, e in a:
        points.add(s)
        points.add(e)
    for s, e in b:
        points.add(s)
        points.add(e)

    points = sorted(points)

    if not points:
        return []

    def covered(x, intervals):
        for s, e in intervals:
            if s <= x < e:
                return True
        return False

    result = []
    for i in range(len(points) - 1):
        x = points[i]
        y = points[i + 1]
        if x >= y:
            continue
        if covered(x, a) and not covered(x, b):
            if result and result[-1][1] == x:
                result[-1][1] = y
            else:
                result.append([x, y])

    return result

